-- Repair the audited native achievement criteria through Dragons of Norrath.
-- Generated from the current reviewed mappings and the ToB resource snapshot.
-- Scope: 540 criteria across exactly 510 component identities / 98 achievements.
-- Events: 436 NPC-name kills, 66 task completions, 22 owned items,
-- and 16 achievement dependencies. Manual quest criteria are intentionally excluded.
-- Existing criteria on these exact components are disabled before the authoritative
-- rows are upserted. No achievement enable state, rewards, definitions, or
-- character achievement state is changed.

SET NAMES utf8mb4;
START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS `_achievement_native_repair_components`;
CREATE TEMPORARY TABLE `_achievement_native_repair_components` (
	`achievement_id` INT(10) UNSIGNED NOT NULL,
	`component_type` TINYINT(3) UNSIGNED NOT NULL,
	`component_id` INT(10) UNSIGNED NOT NULL,
	PRIMARY KEY (`achievement_id`, `component_type`, `component_id`)
) ENGINE=InnoDB;




-- Converge these audited components: disable obsolete event/target alternatives
-- before re-enabling the current authoritative identities below.
UPDATE `achievement_criteria` AS criteria
JOIN `_achievement_native_repair_components` AS audited
	ON audited.`achievement_id` = criteria.`achievement_id`
	AND audited.`component_type` = criteria.`component_type`
	AND audited.`component_id` = criteria.`component_id`
SET criteria.`enabled` = 0;

-- Generate only structurally validated evaluation criteria.
-- Existing criteria with other identities remain untouched.
ON DUPLICATE KEY UPDATE
	`component_sequence` = VALUES(`component_sequence`),
	`progress_mode` = VALUES(`progress_mode`),
	`behavior` = VALUES(`behavior`),
	`target_value` = VALUES(`target_value`),
	`required_count` = VALUES(`required_count`),
	`enabled` = VALUES(`enabled`);

ON DUPLICATE KEY UPDATE
	`component_sequence` = VALUES(`component_sequence`),
	`progress_mode` = VALUES(`progress_mode`),
	`behavior` = VALUES(`behavior`),
	`target_value` = VALUES(`target_value`),
	`required_count` = VALUES(`required_count`),
	`enabled` = VALUES(`enabled`);

ON DUPLICATE KEY UPDATE
	`component_sequence` = VALUES(`component_sequence`),
	`progress_mode` = VALUES(`progress_mode`),
	`behavior` = VALUES(`behavior`),
	`target_value` = VALUES(`target_value`),
	`required_count` = VALUES(`required_count`),
	`enabled` = VALUES(`enabled`);

COMMIT;

-- Expected result: 510 enabled components and 540 enabled criteria.
SELECT
	COUNT(DISTINCT criteria.`achievement_id`, criteria.`component_type`,
		criteria.`component_id`) AS `enabled_components`,
	COUNT(*) AS `enabled_criteria`
FROM `achievement_criteria` AS criteria
JOIN `_achievement_native_repair_components` AS audited
	ON audited.`achievement_id` = criteria.`achievement_id`
	AND audited.`component_type` = criteria.`component_type`
	AND audited.`component_id` = criteria.`component_id`
WHERE criteria.`enabled` = 1;

-- Expected event counts: 4=66, 7=22, 11=16, 12=436.
SELECT criteria.`event_type`, COUNT(*) AS `enabled_criteria`
FROM `achievement_criteria` AS criteria
JOIN `_achievement_native_repair_components` AS audited
	ON audited.`achievement_id` = criteria.`achievement_id`
	AND audited.`component_type` = criteria.`component_type`
	AND audited.`component_id` = criteria.`component_id`
WHERE criteria.`enabled` = 1
GROUP BY criteria.`event_type`
ORDER BY criteria.`event_type`;

DROP TEMPORARY TABLE IF EXISTS `_achievement_native_repair_components`;
